-- Retiro recuperable de movimientos históricos capturados por error.
-- No elimina asignaciones ni referencias y no toca la fuente SAP.
SET @ddl = IF(EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='activo_asignaciones' AND column_name='archived_at'),'SELECT 1','ALTER TABLE activo_asignaciones ADD COLUMN archived_at DATETIME NULL AFTER unassigned_at'); PREPARE stmt FROM @ddl; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @ddl = IF(EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='activo_asignaciones' AND column_name='archived_by'),'SELECT 1','ALTER TABLE activo_asignaciones ADD COLUMN archived_by CHAR(36) NULL AFTER archived_at'); PREPARE stmt FROM @ddl; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @ddl = IF(EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='activo_asignaciones' AND column_name='archive_reason'),'SELECT 1','ALTER TABLE activo_asignaciones ADD COLUMN archive_reason VARCHAR(1000) NULL AFTER archived_by'); PREPARE stmt FROM @ddl; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @ddl = IF(EXISTS(SELECT 1 FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name='activo_asignaciones' AND index_name='idx_asignaciones_history_visible'),'SELECT 1','ALTER TABLE activo_asignaciones ADD KEY idx_asignaciones_history_visible (asset_uid, archived_at, assigned_at)'); PREPARE stmt FROM @ddl; EXECUTE stmt; DEALLOCATE PREPARE stmt;
